definedNames.JSON_ESCAPE:
LAMBDA(text, SUBSTITUTE(
  SUBSTITUTE(
    SUBSTITUTE(
      SUBSTITUTE(
        SUBSTITUTE(text, "\", "\\"),
        """", "\"""
      ),
      CHAR(10), "\n"
    ),
    CHAR(13), "\r"
  ),
  CHAR(9), "\t"
))

cells.formula:
ADD_EMPTY_ROW(MAP(SPLITSHEET_COL($C:$C), LAMBDA(c,
  IfError(LET(
    sn, REGEXEXTRACT(c, "^[^!]+"),
    pairs, {"Tx"&UNICHAR(8239),"D5";"Tp","D6";"Dis"&UNICHAR(8239),"D7"},
    TEXTJOIN(" - ", TRUE,
      BYROW(pairs, LAMBDA(rw,
        LET(
          title, INDEX(rw,1,1),
          addr,  INDEX(rw,1,2),
          val, Round(INDIRECT(sn & "!" & addr),2),
          if(val>0,title & ": " & TEXT(val, "#,##0"""&UNICHAR(8239)&""".00"),"")
        )
      ))
    )
  ),)
)))

