cells.formula:
=ADD_EMPTY_ROW(IF(_xlfn.ISFORMULA(D9),
  LET(
    sheetNames, GETSHEETNAMES(D9,false),
    IF(COUNTA(sheetNames)=0,,
      REDUCE(, sheetNames, LAMBDA(acc, sheet,
        LET(
          range, INDIRECT(sheet&"!A:A"),
          maxRow, LAST_ROW(range),
          refs, IF(maxRow>=G3, sheet&"!F"&SEQUENCE(maxRow-G3+1,1,G3),),
          IF(acc="", refs, VSTACK(acc, refs))
        )
      ))
    )
  ),
))

ADD_EMPTY_ROW(ArrayFormula(
  IF(LEN(SPLITSHEET_COL(C:C)) > 0,
    IF(REGEXMATCH(
         BYROW(Offset(SPLITSHEET_COL(M:M),0,0,,L3-Column(M1)+1), LAMBDA(row, JOIN(",", row))),
         "^" & SUBSTITUTE(REGEXREPLACE(SPLITSHEET_COL(L:L), ",+$", ), ".", "\.") & ",*$"
       ),
       ,
       1
    ),
  )
))

ADD_EMPTY_ROW(
  LET(
    colC, SPLITSHEET_COL(C:C),
    countC, COUNTA(colC),
    IF(
      countC = 0,,
      ARRAYFORMULA(
        REGEXEXTRACT(
          MAP(
            ARRAY_CONSTRAIN(colC, countC, 1),
            LAMBDA(addr, INDIRECT(addr))
          ),"(?:[^,]*(?:,)){0," & ($L$3 - 1 - 12) & "}[^,]*"
        )
      )
    )
  )
)
